<?php
require_once __DIR__ . '/bootstrap.php'; require_admin();
$counts = [];
foreach (['categories'=>'Danh mục','products'=>'Sản phẩm','orders'=>'Đơn hàng','users'=>'Người dùng'] as $table=>$label) { $counts[$table] = (int)$conn->query("SELECT COUNT(*) FROM `$table`")->fetchColumn(); }
$pending = (int)$conn->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn();
$recent = $conn->query("SELECT o.id,o.total_amount,o.status,o.created_at,o.phone,o.shipping_address,u.full_name FROM orders o LEFT JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 8")->fetchAll(PDO::FETCH_ASSOC);
admin_header('Tổng quan');
?><div class="stats"><div class="card"><div class="stat-label">Danh mục</div><div class="stat-number"><?= $counts['categories'] ?></div><a href="<?= h(admin_url('categories/index.php')) ?>">Quản lý danh mục →</a></div><div class="card"><div class="stat-label">Sản phẩm</div><div class="stat-number"><?= $counts['products'] ?></div><a href="<?= h(admin_url('products/index.php')) ?>">Quản lý sản phẩm →</a></div><div class="card"><div class="stat-label">Tổng đơn hàng</div><div class="stat-number"><?= $counts['orders'] ?></div><a href="<?= h(admin_url('orders/index.php')) ?>">Xem đơn hàng →</a></div><div class="card"><div class="stat-label">Đơn đang chờ xử lý</div><div class="stat-number"><?= $pending ?></div><span class="text-muted">Người dùng: <?= $counts['users'] ?></span></div></div><section class="card"><div class="toolbar"><h2 style="margin:0">Đơn hàng gần đây</h2><a class="btn" href="<?= h(admin_url('orders/index.php')) ?>">Xem tất cả</a></div><div class="table-wrap"><table><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày đặt</th><th>Tổng tiền</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php if (!$recent): ?><tr><td colspan="6" class="empty">Chưa có đơn hàng.</td></tr><?php else: foreach ($recent as $o): ?><tr><td>#<?= (int)$o['id'] ?></td><td><?= h($o['full_name'] ?: 'Tài khoản đã xóa') ?></td><td><?= h($o['created_at']) ?></td><td><?= h(money($o['total_amount'])) ?></td><td><span class="badge badge-<?= h($o['status']) ?>"><?= h(['pending'=>'Chờ xử lý','processing'=>'Đang xử lý','completed'=>'Hoàn thành','cancelled'=>'Đã hủy'][$o['status']] ?? $o['status']) ?></span></td><td><a class="btn btn-small" href="<?= h(admin_url('orders/detail.php?id='.(int)$o['id'])) ?>">Chi tiết</a></td></tr><?php endforeach; endif; ?></tbody></table></div></section><?php admin_footer(); ?>
